function makeChecker(limit) {
  try {
    return (amount) => {
      if (amount > limit) {
        throw new Error("over the limit");
      }

      return "ok";
    };
  } catch {
    console.log("caught in makeChecker");
  }
}

const check = makeChecker(100);

console.log(check(50));

try {
  console.log(check(500));
} catch (error) {
  console.log("caught outside: " + error.message);
}
